// /learn/hebrew-verbs/ and /fr/apprendre/conjugaison-hebreu/ — the verb conjugation
// tool. Data: src/data/hebrew-verbs.json, generated by scripts/import-app-verbs.mjs
// from the app's verb dictionary (docs/VERBS.md). Only `free` verbs carry forms.
import verbData from '../data/hebrew-verbs.json' with { type: 'json' };

export const verbsPath = '/learn/hebrew-verbs/';
export const verbsPathFr = '/fr/apprendre/conjugaison-hebreu/';
export const verbsPublishedAt = '2026-11-03';

/** Verbs in the app's dictionary (the site lists every one with a translation). */
export const appVerbCount = verbData.source.count;

// Same order and colors as the app's binyan chips (VerbExplorerScreen.binyanColor).
// `example` is the free verb the chart row conjugates: active/passive pairs share
// a root (כתב, דבר, בין) so the chart shows one root moving through patterns.
export const binyanim = [
  { id: 'paal', name: "Pa'al", he: 'פָּעַל', color: '#6366F1', example: 'likhtov' },
  { id: 'nifal', name: "Nif'al", he: 'נִפְעַל', color: '#F59E0B', example: 'lehikatev' },
  { id: 'piel', name: "Pi'el", he: 'פִּעֵל', color: '#10B981', example: 'ledaber' },
  { id: 'pual', name: "Pu'al", he: 'פֻּעַל', color: '#4F46E5', example: 'dubar' },
  { id: 'hifil', name: "Hif'il", he: 'הִפְעִיל', color: '#F97316', example: 'lehavin' },
  { id: 'hufal', name: "Huf'al", he: 'הֻפְעַל', color: '#059669', example: 'huvan' },
  { id: 'hitpael', name: "Hitpa'el", he: 'הִתְפַּעֵל', color: '#DC2626', example: 'lehitkasher' },
];

// Hero: one root, two binyanim — every id is a free verb.
export const rootPairs = [
  { root: 'ל־מ־ד', ids: ['lilmod', 'lelamed'] },
  { root: 'כ־ת־ב', ids: ['likhtov', 'lehikatev'] },
  { root: 'ב־י־ן', ids: ['lehavin', 'huvan'] },
];

// Hero shortcuts under the search box: everyday free verbs (the default card,
// likhtov, is already open further down).
export const heroPopular = ['ledaber', 'leekhol', 'lalekhet', 'lehavin'];

// "How it works" cards, one per verbs.howSteps entry: [verb id, form key] pairs
// rendered from the data, so the Hebrew in the explanation is never retyped.
export const howExamples = [
  [['likhtov', 'infinitive'], ['lehikatev', 'infinitive']],
  [['likhtov', 'present_ms'], ['likhtov', 'present_fs'], ['likhtov', 'present_mp'], ['likhtov', 'present_fp']],
  [['likhtov', 'past_1s'], ['likhtov', 'past_2ms'], ['likhtov', 'past_3fs'], ['likhtov', 'past_1p']],
  [['likhtov', 'future_1s'], ['likhtov', 'future_2ms'], ['likhtov', 'future_3ms'], ['likhtov', 'future_1p']],
];

// Row order inside each tense block, singular before plural (as in most grammars).
export const tenseRows = {
  present: ['present_ms', 'present_fs', 'present_mp', 'present_fp'],
  past: ['past_1s', 'past_2ms', 'past_2fs', 'past_3ms', 'past_3fs', 'past_1p', 'past_2mp', 'past_2fp', 'past_3pl'],
  future: ['future_1s', 'future_2ms', 'future_2fs', 'future_3ms', 'future_3fs', 'future_1p', 'future_2mp', 'future_2fp', 'future_3mp', 'future_3fp'],
  imperative: ['imperative_ms', 'imperative_fs', 'imperative_mp', 'imperative_fp'],
};

// The Hebrew pronoun(s) shown beside each form. Present and imperative forms
// agree in gender/number only, so they list every pronoun the form serves.
export const formPronouns = {
  present_ms: 'אֲנִי, אַתָּה, הוּא', present_fs: 'אֲנִי, אַתְּ, הִיא', present_mp: 'אֲנַחְנוּ, אַתֶּם, הֵם', present_fp: 'אֲנַחְנוּ, אַתֶּן, הֵן',
  past_1s: 'אֲנִי', past_2ms: 'אַתָּה', past_2fs: 'אַתְּ', past_3ms: 'הוּא', past_3fs: 'הִיא', past_1p: 'אֲנַחְנוּ', past_2mp: 'אַתֶּם', past_2fp: 'אַתֶּן', past_3pl: 'הֵם, הֵן',
  future_1s: 'אֲנִי', future_2ms: 'אַתָּה', future_2fs: 'אַתְּ', future_3ms: 'הוּא', future_3fs: 'הִיא', future_1p: 'אֲנַחְנוּ', future_2mp: 'אַתֶּם', future_2fp: 'אַתֶּן', future_3mp: 'הֵם', future_3fp: 'הֵן',
  imperative_ms: 'אַתָּה', imperative_fs: 'אַתְּ', imperative_mp: 'אַתֶּם', imperative_fp: 'אַתֶּן',
};

export const verbs = verbData.verbs;
export const freeVerbs = verbData.free.map(id => verbs.find(v => v.id === id));
export const verbById = id => verbs.find(v => v.id === id);

/** The client explorer's index: headwords only, never a locked verb's forms. */
export function verbIndex(locale) {
  return verbs.map(v => ({ id: v.id, b: v.binyan, he: v.he, root: v.root, tr: v.tr[locale], ...(v.free ? { free: 1, tl: v.translit[locale] } : {}) }));
}

export function verbsSitemapEntries() {
  return [
    { url: verbsPath, lastmod: verbsPublishedAt, priority: '0.8', changefreq: 'monthly' },
    { url: verbsPathFr, lastmod: verbsPublishedAt, priority: '0.8', changefreq: 'monthly' },
  ];
}

export function verbsSchema(locale, { title, description, home, page }) {
  const url = `https://hebrewedu.com${locale === 'fr' ? verbsPathFr : verbsPath}`;
  return { '@context': 'https://schema.org', '@graph': [
    { '@type': 'WebPage', '@id': `${url}#webpage`, url, name: title, description, inLanguage: [locale, 'he'] },
    { '@type': 'BreadcrumbList', itemListElement: [
      { '@type': 'ListItem', position: 1, name: home, item: `https://hebrewedu.com${locale === 'fr' ? '/fr/' : '/'}` },
      { '@type': 'ListItem', position: 2, name: page, item: url },
    ] },
  ] };
}
